// Descobre o tribunal a partir do próprio número CNJ.
// Formato: NNNNNNN-DD.AAAA.J.TR.OOOO  ->  J = segmento, TR = tribunal
// (Resolução CNJ 65/2008)
//
// Exige exatamente 20 dígitos. Não completa com zero à esquerda: um número
// curto preenchido desloca as posições e pode cair num tribunal válido por
// acaso — o protocolo "08650.216736/2024-31" (SEI da PRF) virava TRE-RN e
// seria consultado como se fosse processo judicial.
const mapaTribunais = {
  '3-00': 'stj',
  '4-01': 'trf1', '4-02': 'trf2', '4-03': 'trf3', '4-04': 'trf4', '4-05': 'trf5', '4-06': 'trf6',
  '5-00': 'tst',
  '5-01': 'trt1', '5-02': 'trt2', '5-03': 'trt3', '5-04': 'trt4', '5-05': 'trt5',
  '5-06': 'trt6', '5-07': 'trt7', '5-08': 'trt8', '5-09': 'trt9', '5-10': 'trt10',
  '5-11': 'trt11', '5-12': 'trt12', '5-13': 'trt13', '5-14': 'trt14', '5-15': 'trt15',
  '5-16': 'trt16', '5-17': 'trt17', '5-18': 'trt18', '5-19': 'trt19', '5-20': 'trt20',
  '5-21': 'trt21', '5-22': 'trt22', '5-23': 'trt23', '5-24': 'trt24',
  '6-00': 'tse',
  '6-01': 'tre-ac', '6-02': 'tre-al', '6-03': 'tre-ap', '6-04': 'tre-am', '6-05': 'tre-ba',
  '6-06': 'tre-ce', '6-07': 'tre-dft', '6-08': 'tre-es', '6-09': 'tre-go', '6-10': 'tre-ma',
  '6-11': 'tre-mt', '6-12': 'tre-ms', '6-13': 'tre-mg', '6-14': 'tre-pa', '6-15': 'tre-pb',
  '6-16': 'tre-pr', '6-17': 'tre-pe', '6-18': 'tre-pi', '6-19': 'tre-rj', '6-20': 'tre-rn',
  '6-21': 'tre-rs', '6-22': 'tre-ro', '6-23': 'tre-rr', '6-24': 'tre-sc', '6-25': 'tre-se',
  '6-26': 'tre-sp', '6-27': 'tre-to',
  '8-01': 'tjac', '8-02': 'tjal', '8-03': 'tjap', '8-04': 'tjam', '8-05': 'tjba',
  '8-06': 'tjce', '8-07': 'tjdft', '8-08': 'tjes', '8-09': 'tjgo', '8-10': 'tjma',
  '8-11': 'tjmt', '8-12': 'tjms', '8-13': 'tjmg', '8-14': 'tjpa', '8-15': 'tjpb',
  '8-16': 'tjpr', '8-17': 'tjpe', '8-18': 'tjpi', '8-19': 'tjrj', '8-20': 'tjrn',
  '8-21': 'tjrs', '8-22': 'tjro', '8-23': 'tjrr', '8-24': 'tjsc', '8-25': 'tjse',
  '8-26': 'tjsp', '8-27': 'tjto',
  '9-13': 'tjmmg', '9-21': 'tjmrs', '9-26': 'tjmsp'
};

return $input.all().map(item => {
  const numero = item.json.numero;
  const numeroLimpo = String(numero || '').replace(/\D/g, '');

  let indice = null;
  if (numeroLimpo.length === 20) {
    const j = String(parseInt(numeroLimpo.substring(13, 14), 10));
    const tr = numeroLimpo.substring(14, 16);
    indice = mapaTribunais[`${j}-${tr}`] || null;
  }

  return {
    json: {
      rowId: item.json.rowId,
      numero: item.json.numeroNaTabela || numero,
      numeroLimpo,
      indice,
      url: indice ? `https://api-publica.datajud.cnj.jus.br/api_publica_${indice}/_search` : null
    }
  };
});

// Junta as movimentações de TODAS as instâncias e pega a mais recente.
//
// Um mesmo número CNJ pode ter mais de um documento no DataJud: G1 (origem) e
// G2 (recurso). Numa amostra de 40 processos reais, 8 vieram com os dois e em
// 4 deles o primeiro hit NÃO era o mais recente — o Elasticsearch devolve por
// relevância, não por data. Pegar hits[0] esconderia decisão do recurso.
//
// Também não usa dataHoraUltimaAtualizacao: esse carimbo muda quando o tribunal
// apenas reindexa o processo, sem andamento novo.
//
// A ordenação por data não é luxo: numa amostra de 61 documentos reais, 93%
// vieram com os movimentos fora de ordem cronológica dentro do próprio array.
//
// Graus vistos na base: G1, JE, G2 e TR (nesta ordem de frequência).
const INSTANCIA = {
  G1: '1ª inst.',
  G2: '2ª inst.',
  JE: 'Juizado Especial',
  TR: 'Turma Recursal',
  SUP: 'Tribunal Superior'
};
const saida = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  let origem = {};
  try { origem = $('Identificar Tribunal').itemMatching(i).json; } catch (e) { origem = {}; }

  const hits = entradas[i].json?.hits?.hits || [];
  const numero = origem.numero || hits[0]?._source?.numeroProcesso || null;

  // todas as movimentações, de todos os documentos, marcadas com a instância
  const todas = [];
  for (const h of hits) {
    const p = h._source || {};
    for (const m of (p.movimentos || [])) {
      todas.push({ ...m, grau: p.grau || null, classe: p.classe?.nome || null });
    }
  }

  if (!todas.length) {
    saida.push({ json: { numero, rowId: origem.rowId, semRegistro: true } });
    continue;
  }

  todas.sort((a, b) => new Date(b.dataHora) - new Date(a.dataHora));
  const ultimo = todas[0];

  saida.push({
    json: {
      numero,
      rowId: origem.rowId,
      semRegistro: false,
      instancias: hits.length,
      totalMovimentos: todas.length,
      movimento: {
        codigo: ultimo.codigo,
        nome: ultimo.nome,
        dataHora: ultimo.dataHora,
        complementosTabelados: ultimo.complementosTabelados || [],
        grau: ultimo.grau,
        instancia: INSTANCIA[ultimo.grau] || ultimo.grau || null,
        classe: ultimo.classe
      }
    }
  });
}

return saida;

// Consolida a execução num item só, para ficar legível no histórico do n8n.
// Quem decide se houve mudança é o CRM; aqui só se lê o veredito.
const itens = $input.all().map(i => i.json || {});
const conta = (s) => itens.filter(i => i.status === s).length;

const atualizados = itens
  .filter(i => i.status === 'atualizado')
  .map(i => ({
    movimentacao: i.movimentacao,
    data: i.dataMovimentacao,
    anterior: i.anterior || '(vazio)'
  }));

return [{
  json: {
    quando: new Date().toISOString(),
    processados: itens.length,
    atualizados: conta('atualizado'),
    sem_mudanca: conta('sem_mudanca'),
    nao_encontrados_no_crm: conta('nao_encontrado'),
    com_erro: itens.filter(i => i.error).length,
    detalhe_atualizados: atualizados
  }
}];

// Processo que o DataJud não retornou: pode ser sigiloso, ainda não indexado,
// ou de tribunal que não publica na API pública. Não é falha do fluxo.
return [{
  json: {
    tipo: 'sem registro no DataJud',
    quantidade: $input.all().length,
    numeros: $input.all().map(i => i.json.numero)
  }
}];

// Número que não casa com nenhum tribunal conhecido — quase sempre é número
// digitado errado no cadastro. Vale conferir esta lista de vez em quando.
return [{
  json: {
    tipo: 'tribunal não identificado pelo número CNJ',
    quantidade: $input.all().length,
    numeros: $input.all().map(i => i.json.numero)
  }
}];
